/* Generated by scripts/build-fallback.php — edit resources/js/room-grid.js instead. */
/*
|------------------------------------------------------------------------------
| Room Calendar — the tile grid and the guest panel
|------------------------------------------------------------------------------
| Clicking a tile fills the panel on the right without reloading the page, and
| points the Check In / Check Out buttons at that room's guest.
|
| Everything the buttons do still goes through a normal link, so the screen
| degrades to "click a tile, read the page" if this file never loads.
*/

(function () {
    'use strict';

    const boot = window.RC_BOOT || {};
    const grid = document.querySelector('[data-rooms]');
    const panel = document.querySelector('[data-guest-panel]');

    if (!grid || !panel) return;

    const $ = (sel, root) => (root || document).querySelector(sel);
    const $$ = (sel, root) => Array.prototype.slice.call((root || document).querySelectorAll(sel));

    const empty = $('[data-guest-empty]', panel);
    const info = $('[data-guest-info]', panel);
    const checkOut = $('[data-guest-checkout]', panel);
    const checkIn = $('[data-guest-checkin]', panel);
    const hkRoom = $('[data-hk-room]');
    const hkSave = $('[data-hk-save]');

    function setButton(button, href) {
        if (!button) return;

        button.href = href || '#';
        button.classList.toggle('is-disabled', !href);
        button.setAttribute('aria-disabled', href ? 'false' : 'true');
    }

    function fill(data) {
        if (!data || !data.found) return;

        $$('[data-info]', panel).forEach(function (cell) {
            const value = data[cell.getAttribute('data-info')];

            cell.textContent = value === null || value === undefined || value === '' ? '--' : value;
        });

        if (empty) empty.hidden = true;
        if (info) info.hidden = false;

        setButton(
            checkOut,
            data.can_check_out ? boot.checkOutUrl + '?check_in=' + data.check_in_id : null
        );

        setButton(
            checkIn,
            data.can_check_in ? boot.checkInUrl + '?reservation=' + data.reservation_id : null
        );

        if (hkRoom) hkRoom.value = data.room_id;

        if (hkSave) {
            hkSave.disabled = false;
            hkSave.classList.remove('is-disabled');
        }
    }

    grid.addEventListener('click', function (event) {
        const tile = event.target.closest('[data-room]');
        if (!tile) return;

        $$('.nv-rc-tile.is-picked', grid).forEach((t) => t.classList.remove('is-picked'));
        tile.classList.add('is-picked');

        fetch(boot.guestUrl + '?room=' + encodeURIComponent(tile.getAttribute('data-room'))
            + '&date=' + encodeURIComponent(boot.date), { headers: { Accept: 'application/json' } })
            .then((r) => (r.ok ? r.json() : null))
            .then(fill)
            .catch(function () {
                // Offline: the tile stays picked, the panel keeps what it had.
            });
    });

    // A room picked before the page reloaded keeps its buttons working.
    const picked = $('.nv-rc-tile.is-picked', grid);

    if (picked) {
        picked.click();
    }
})();
